/**
 * Concatenate supabase/migrations/*.sql (in order) into one file you can paste into the
 * Supabase SQL Editor in a single step.
 *
 *   npm run db:bundle            → supabase/.generated/setup.sql
 *   npm run db:bundle -- --seed  → also appends supabase/seed.sql (local/dev projects only!)
 *
 * The generated file is gitignored: the individual migrations stay the source of truth.
 */
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'

const root = path.resolve(import.meta.dirname, '..')
const migrationsDir = path.join(root, 'supabase/migrations')
const outFile = path.join(root, 'supabase/.generated/setup.sql')
const withSeed = process.argv.includes('--seed')

const files = (await readdir(migrationsDir)).filter((f) => f.endsWith('.sql')).sort()
const parts = [`-- Generated by scripts/bundle-migrations.mjs on ${new Date().toISOString()}. Do not edit.\n`]
for (const file of files) {
  parts.push(`\n-- ======== ${file} ========\n`, await readFile(path.join(migrationsDir, file), 'utf8'))
}
if (withSeed) parts.push('\n-- ======== seed.sql (development data) ========\n', await readFile(path.join(root, 'supabase/seed.sql'), 'utf8'))

await mkdir(path.dirname(outFile), { recursive: true })
await writeFile(outFile, parts.join(''))
console.log(`Wrote ${path.relative(root, outFile)} (${files.length} migrations${withSeed ? ' + seed' : ''})`)
